#include <stdio.h>
#include <string.h>

#define MOD 1000000007LL
#define MAXN 1005

long long E[MAXN][MAXN];
long long pw(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = result * base % mod;
        base = base * base % mod;
        exp >>= 1;
    }
    return result;
}

long long inv(long long a) {
    return pw(a % MOD, MOD - 2, MOD);
}

int main() {
    int N, A, B, C;
    scanf("%d %d %d %d", &N, &A, &B, &C);

    long long mod = MOD;
    long long inv_AB = inv((A + B) % mod);
    long long coeff_const = 100LL * inv_AB % mod;
    long long coeff_A = (long long)A * inv_AB % mod;
    long long coeff_B = (long long)B * inv_AB % mod;

    // E[N][j] = 0 for all j, E[i][N] = 0 for all i
    // Fill DP: i from N-1 down to 0, j from N-1 down to 0
    // But we need E[i+1][j] and E[i][j+1]
    // So iterate i from N-1 to 0, j from N-1 to 0

    memset(E, 0, sizeof(E));

    for (int i = N - 1; i >= 0; i--) {
        for (int j = N - 1; j >= 0; j--) {
            long long val = coeff_const;
            val = (val + coeff_A * E[i+1][j]) % mod;
            val = (val + coeff_B * E[i][j+1]) % mod;
            E[i][j] = val;
        }
    }

    printf("%lld\n", E[0][0]);
    return 0;
}

#include <stdio.h>

#define MOD 1000000007LL

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    a %= MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

long long Ccomb[2005][2005];

int main(void) {
    int N;
    long long A, B, C;
    scanf("%d %lld %lld %lld", &N, &A, &B, &C);

    long long inv100 = modpow(100, MOD - 2);
    long long s = (A + B) % MOD;
    long long invS = modpow(s, MOD - 2);

    long long pA = A % MOD * invS % MOD;
    long long pB = B % MOD * invS % MOD;

    long long drawFactor = 100LL * modpow((100 - C) % MOD, MOD - 2) % MOD;

    int maxn = 2 * N;
    for (int i = 0; i <= maxn; i++) {
        Ccomb[i][0] = Ccomb[i][i] = 1;
        for (int j = 1; j < i; j++) {
            Ccomb[i][j] = (Ccomb[i - 1][j - 1] + Ccomb[i - 1][j]) % MOD;
        }
    }

    long long powA[2005], powB[2005];
    powA[0] = powB[0] = 1;
    for (int i = 1; i <= N; i++) {
        powA[i] = powA[i - 1] * pA % MOD;
        powB[i] = powB[i - 1] * pB % MOD;
    }

    long long ans = 0;

    for (int k = 0; k < N; k++) {
        long long ways = Ccomb[N - 1 + k][k];

        long long probT = ways * powA[N] % MOD * powB[k] % MOD;
        long long gamesT = N + k;
        ans = (ans + probT * gamesT) % MOD;

        long long probA = ways * powB[N] % MOD * powA[k] % MOD;
        long long gamesA = N + k;
        ans = (ans + probA * gamesA) % MOD;
    }

    ans = ans * drawFactor % MOD;

    printf("%lld\n", ans);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 1e9 + 7;

int64 modinv(int64 a) {
    int64 b = MOD, u = 1, v = 0;
    while (b) {
        int64 t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= MOD;
    if (u < 0) u += MOD;
    return u;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 N, A, B, C;
    cin >> N >> A >> B >> C;

    int64 inv100 = modinv(100);
    int64 p = A * inv100 % MOD; // Takahashi win prob
    int64 q = B * inv100 % MOD; // Aoki win prob
    int64 r = C * inv100 % MOD; // draw prob

    // dp[i][j] = expected remaining games from (i, j)
    vector<vector<int64>> dp(N, vector<int64>(N, 0));

    // For boundary states, we already know expectation = 0 when game ends,
    // but we compute from states where one player has N wins.
    // We'll fill dp backwards: from states where i==N or j==N, expected=0.

    // Transition: dp[i][j] = 1 + p*dp[i+1][j] + q*dp[i][j+1] + r*dp[i][j]
    // => (1 - r) * dp[i][j] = 1 + p*dp[i+1][j] + q*dp[i][j+1]
    // => dp[i][j] = (1 + p*dp[i+1][j] + q*dp[i][j+1]) * inv(1-r) mod MOD

    int64 inv_1_minus_r = modinv((1 - r + MOD) % MOD);

    for (int i = N - 1; i >= 0; i--) {
        for (int j = N - 1; j >= 0; j--) {
            int64 term = 1;
            if (i + 1 < N) term = (term + p * dp[i+1][j]) % MOD;
            else term = (term + p * 0) % MOD; // game ends, no further

            if (j + 1 < N) term = (term + q * dp[i][j+1]) % MOD;
            else term = (term + q * 0) % MOD;

            dp[i][j] = term * inv_1_minus_r % MOD;
        }
    }

    cout << dp[0][0] << "\n";
    return 0;
}

