    cin >> N >> A >> B >> C;

    long long inv100 = inv(100);
    long long p = A % MOD * inv100 % MOD;
    long long q = B % MOD * inv100 % MOD;
    long long pq_inv = inv((A + B) % MOD * inv100 % MOD);

    // E[i][j]: expected games from state (i wins for T, j wins for A)
    vector<vector<long long>> E(N + 1, vector<long long>(N + 1, 0));

    for (int i = N - 1; i >= 0; i--) {
        for (int j = N - 1; j >= 0; j--) {
            long long val = 1;
            val = (val + p % MOD * E[i + 1][j]) % MOD;
            val = (val + q % MOD * E[i][j + 1]) % MOD;
            E[i][j] = val % MOD * pq_inv % MOD;
